  const load = (c, o, files) => { for (const f of files) vm.runInContext(fs.readFileSync(path.join(__dirname, f), 'utf8'), c, { filename: f }); return o; };
  load(ctx, w, BOOT); load(ctx, w, w.FireExamples.files()); load(ctx, w, REST);
