    await rp.mouse.move(rpin[0], rpin[1]); await rp.mouse.down(); const rnow = await rp.evaluate(() => { const r = document.querySelector('.map-pin').getBoundingClientRect(); return [r.left, r.top, window.__w, APP.state.place]; }); await rp.mouse.move(rpin[0] + 12, rpin[1] + 9); const rdrag = await rp.evaluate(() => { const r = document.querySelector('.map-pin').getBoundingClientRect(); return [r.left, r.top]; }); await rp.mouse.up();
    ok(Math.hypot(rnow[0] - rpin[0], rnow[1] - rpin[1]) <= 1.5 && rnow[2] === 1 && rnow[3] === 'fairfax' && Math.hypot(rdrag[0] - rpin[0] - 12, rdrag[1] - rpin[1] - 9) <= 1.5, 'reduced motion: a press places the pin at the pointer at once (one position, no slide), and it follows from there');
