    const rm = await rp.evaluate(async () => { const st = document.querySelector('.stage-layer.on .ba-stage'), line = st.querySelector('.ba-outline-line'); const outline = { drawn: st.classList.contains('is-drawn'), dim: +getComputedStyle(st.querySelector('.ba-dim')).opacity, anim: getComputedStyle(line).animationName, offset: parseFloat(getComputedStyle(line).strokeDashoffset) };
      document.querySelector('#chips button[data-place="fairfax"]').click(); const at = APP.state.place, anims = document.getAnimations().filter(a => !(a instanceof CSSTransition)).length; await new Promise(r => setTimeout(r, 80)); return { outline, at, anims, rows: [...document.querySelectorAll('#localRows .code-row')].map(n => n.dataset.key).join(' '), num: (() => { APP.setPin(-122.6050, 37.9690); return document.querySelector('#localRows [data-key="canopy"] .row-num').textContent; })(), leaving: document.querySelectorAll('.is-leaving').length }; });
    if (!(rm.at === 'fairfax' && rm.anims === 0 && rm.num === '6' && rm.leaving === 0)) console.log('       reduced motion saw', JSON.stringify(rm));
    ok(rm.at === 'fairfax' && rm.anims === 0 && rm.rows === 'ladder-reach hazard-veg canopy roadside brush-nuisance' && rm.num === '6' && rm.leaving === 0 && rerr.length === 0, 'reduced motion: the chip places the pin at once, rules change with no travel, numbers do not count, and no scripted animation ever runs');
