    await rp.evaluate(() => APP.setPin(FireGeo.geo.pins.ross[0], FireGeo.geo.pins.ross[1])); await sleep(300);
    const rfly = await rp.evaluate(async () => { const reg = id => document.querySelector('.map-region[data-region="' + id + '"]'), op = id => { const s = getComputedStyle(reg(id)); return s.visibility === 'visible' ? +s.opacity : 0; }, cams = new Set(), mix = [];
      document.querySelector('#chips button[data-place="berkeley"]').click(); const atOnce = { place: APP.state.place, flying: APP.camera().flying, pin: (() => { const r = document.querySelector('.map-pin').getBoundingClientRect(), c = APP.toClient(FireGeo.geo.pins.berkeley[0], FireGeo.geo.pins.berkeley[1]); return Math.hypot(r.left - c[0], r.top - c[1]); })() };
      const left = () => { const b = document.querySelector('#mapBox').getBoundingClientRect(), r = reg('rossvalley').getBoundingClientRect(); return (r.left - b.left) / b.width; }, at0 = left(); let still = true;
      await new Promise(done => { let k = 0; (function tick() { const c = APP.camera(); cams.add(c.x.toFixed(1) + '/' + c.z.toFixed(3)); const m = [op('rossvalley'), op('berkeley')]; mix.push(m); if (m[0] > 0.03 && m[0] < 0.999 && Math.abs(left() - at0) > 0.002) still = false; if (++k < 30) requestAnimationFrame(tick); else done(); })(); });
      return { atOnce, still, cams: [...cams], faded: mix.filter(m => m[0] > 0.03 && m[0] < 0.97 && m[1] > 0.03 && m[1] < 0.97).length, dark: mix.filter(m => m[0] + m[1] < 0.6).length, end: mix[mix.length - 1], rows: document.querySelectorAll('#localRows .code-row:not(.is-leaving)').length, tr: [...document.querySelectorAll('.map-region')].map(r => r.style.transform.replace(/[\d.]+%/g, m => (+m.slice(0, -1)).toFixed(0) + '%')).join(' | ') }; });
    ok(rfly.atOnce.place === 'berkeley' && !rfly.atOnce.flying && rfly.atOnce.pin < 1.5 && rfly.still && rfly.cams.length === 1 && rfly.faded >= 3 && rfly.dark === 0 && rfly.end[1] === 1 && rfly.rows === 7, 'reduced motion: pressing Berkeley does not travel. The pin and the panel are there at once and the two maps crossfade in place (' + rfly.faded + ' frames with both showing, none blank, the Ross Valley picture not moving as it fades)');
