    // phone width: the cards stack and nothing overflows sideways
    const mctx = await br.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true }), mp = await mctx.newPage(), merr = []; mp.on('pageerror', e => merr.push(e.message)); await look(mp);
